from typing import List, Tuple

def f(inputs: List[Tuple[int, int, List[Tuple[int, int, int]]]]):
    all_edges = []
    for i in inputs:
        ns = i[0]
        nl = i[1]
        for edge in i[2]:
            all_edges.append((edge[0], edge[1]))
            all_edges.append((edge[1], edge[0]))

    all_edges.sort()
    collisions = {}
    for fromVtx, toVtx in all_edges:
        if fromVtx > toVtx:
            fromVtx, toVtx = toVtx, fromVtx
        collision_idx = collisions.get(fromVtx, set())
        collision_idx.add(toVtx)
        collisions[fromVtx] = collision_idx

    res = set()
    cycle_cnt = [0] * (ns + 1)
    for fr, to in collisions.items():
        cycle_cnt[fr] += len(to) - 1
        for to vtx in to:
            if fr!= to and cycle_cnt[fr]: res.add((fr,to))
            if fr!= to and cycle_cnt[vtx]: res.add((to,vtx))

    return res

